import heapq

class TaskManager:
    def __init__(self, tasks):
        # Map: taskId -> (userId, priority)
        self.info = {}
        # Max-heap emulated with (-priority, -taskId): highest priority, then highest taskId
        self.heap = []
        for userId, taskId, priority in tasks:
            self.add(userId, taskId, priority)

    def add(self, userId, taskId, priority):
        self.info[taskId] = (userId, priority)
        heapq.heappush(self.heap, (-priority, -taskId))

    def edit(self, taskId, newPriority):
        userId, _ = self.info[taskId]
        self.info[taskId] = (userId, newPriority)
        heapq.heappush(self.heap, (-newPriority, -taskId))  # old entry becomes stale

    def rmv(self, taskId):
        del self.info[taskId]  # heap entries become stale (lazy deletion)

    def execTop(self):
        while self.heap:
            neg_priority, neg_task = heapq.heappop(self.heap)
            taskId = -neg_task
            # Valid only if the task still exists with this exact priority
            if taskId in self.info and self.info[taskId][1] == -neg_priority:
                userId, _ = self.info.pop(taskId)
                return userId
        return -1
